// 上向き（背面視）の構えも「向いている方向＝画面奥へ盾の正面を向けて構える」＝下向きの構えと
// 同じ盾・同じシルエット（平らな上辺＋下端が尖る凧形・9×15）。違うのは重なりだけ＝盾は体の奥に
// あるので体（骨）が手前に描かれ、肋骨の隙間から盾が覗く。∴1枚の 32×32 では fill でなく
// map 0,1（透明セルだけ盾色に置換）で「骨の後ろ」を表現する。位置は下向きの構えを体の中心で
// 鏡像にした値、さらに「構え＝盾を持ち上げる」分だけ上へ（歩行→構えの差分も下向きと同じ）。
// ★横向きの側面帯（skeletonRGuard）を流用してはいけない＝側面帯は盾の正面が画面左右を向く
// ときの形。プレイヤー側も上向きだけ盾を z-index -1＝体の裏に描く（render-chars.js 待機時）。
